<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}">
    <title>Masuk - Gunawan Jaya Steel</title>

    <style>
        :root {
            --ink: #111111;
            --paper: #ffffff;
            --bg: #f5f5f5;
            --line: #e5e5e5;
            --muted: #6b6b6b;
            --danger: #b91c1c;
        }

        * { box-sizing: border-box; }

        body {
            margin: 0;
            min-height: 100vh;
            min-height: 100dvh;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 24px 16px;
            background: var(--bg);
            color: var(--ink);
            font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            -webkit-font-smoothing: antialiased;
        }

        /* ---------- Kartu (mobile dulu) ---------- */
        .card {
            width: 100%;
            max-width: 400px;
            background: var(--paper);
            border: 1px solid var(--line);
            border-radius: 14px;
            padding: 28px 22px 24px;
            box-shadow: 0 1px 2px rgba(0, 0, 0, .04), 0 8px 24px rgba(0, 0, 0, .04);
        }

        .logo {
            display: block;
            width: 160px;
            height: auto;
            margin: 0 auto 20px;
        }

        h1 {
            margin: 0;
            font-size: 22px;
            line-height: 1.3;
            font-weight: 650;
            text-align: center;
            letter-spacing: -.01em;
        }

        .sub {
            margin: 6px 0 24px;
            font-size: 14px;
            color: var(--muted);
            text-align: center;
        }

        .field { margin-bottom: 16px; }
        .field--last { margin-bottom: 0; }

        label {
            display: block;
            margin-bottom: 6px;
            font-size: 13px;
            font-weight: 600;
        }

        input[type="email"],
        input[type="password"],
        input[type="text"] {
            width: 100%;
            height: 48px;
            padding: 0 14px;
            font: inherit;
            font-size: 16px; /* 16px+ mencegah zoom otomatis di iPhone */
            color: var(--ink);
            background: #fff;
            border: 1px solid #d4d4d4;
            border-radius: 8px;
            outline: none;
            transition: border-color .15s, box-shadow .15s;
        }

        input::placeholder { color: #a3a3a3; }

        input:focus {
            border-color: var(--ink);
            box-shadow: 0 0 0 3px rgba(17, 17, 17, .12);
        }

        input.is-invalid { border-color: var(--danger); }
        input.is-invalid:focus { box-shadow: 0 0 0 3px rgba(185, 28, 28, .15); }

        /* Sembunyikan ikon mata/hapus bawaan browser (Edge/Chrome/Safari) supaya hanya ada satu mata */
        input[type="password"]::-ms-reveal,
        input[type="password"]::-ms-clear { display: none; }
        input[type="password"]::-webkit-credentials-auto-fill-button {
            visibility: hidden;
            pointer-events: none;
            position: absolute;
            right: 0;
        }

        /* ---------- Kolom kata sandi + ikon mata ---------- */
        .pw { position: relative; }
        .pw input { padding-right: 52px; }

        .toggle {
            position: absolute;
            top: 50%;
            right: 6px;
            transform: translateY(-50%);
            display: flex;
            align-items: center;
            justify-content: center;
            width: 40px;
            height: 40px;
            padding: 0;
            color: var(--muted);
            background: transparent;
            border: 0;
            border-radius: 8px;
            cursor: pointer;
        }
        .toggle:hover { color: var(--ink); background: #f5f5f5; }
        .toggle:focus-visible { outline: 2px solid var(--ink); outline-offset: 1px; }
        .toggle svg { display: block; width: 20px; height: 20px; }
        .toggle .eye-off { display: none; }
        .toggle.is-visible .eye { display: none; }
        .toggle.is-visible .eye-off { display: block; }

        .error {
            margin: 6px 0 0;
            font-size: 13px;
            color: var(--danger);
        }

        /* ---------- Tombol (diberi jarak dari kolom kata sandi) ---------- */
        .btn {
            display: block;
            width: 100%;
            height: 48px;
            margin-top: 24px;
            font: inherit;
            font-size: 15px;
            font-weight: 600;
            color: #fff;
            background: var(--ink);
            border: 1px solid var(--ink);
            border-radius: 8px;
            cursor: pointer;
            transition: background .15s;
        }
        .btn:hover { background: #2a2a2a; }
        .btn:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
        .btn:disabled { opacity: .65; cursor: wait; }

        .foot {
            margin: 20px 0 0;
            font-size: 12px;
            color: var(--muted);
            text-align: center;
        }

        /* ---------- Tablet ---------- */
        @media (min-width: 640px) {
            .card { max-width: 440px; padding: 36px 36px 30px; }
            .logo { width: 200px; margin-bottom: 22px; }
            h1 { font-size: 26px; }
            input[type="email"], input[type="password"], input[type="text"] { height: 50px; }
            .btn { height: 52px; }
        }

        /* ---------- Desktop (lebih besar) ---------- */
        @media (min-width: 1024px) {
            .card { max-width: 520px; padding: 48px 44px 40px; border-radius: 16px; }
            .logo { width: 240px; margin-bottom: 26px; }
            h1 { font-size: 30px; }
            .sub { margin: 8px 0 32px; font-size: 16px; }
            .field { margin-bottom: 22px; }
            .field--last { margin-bottom: 0; }
            label { margin-bottom: 8px; font-size: 14px; }
            input[type="email"], input[type="password"], input[type="text"] { height: 54px; font-size: 17px; }
            .pw input { padding-right: 58px; }
            .btn { height: 56px; margin-top: 28px; font-size: 16px; }
            .foot { margin-top: 26px; font-size: 13px; }
        }

        @media (max-width: 420px) {
            body { padding: 16px 12px; }
        }

        @media (prefers-reduced-motion: reduce) {
            * { transition: none !important; }
        }
    </style>
</head>
<body>
